#include <iostream>
#include <string>
#include <chrono>

#include "GPU.cuh"
#include "encoder.h"

int main() {
    HVCache cache(10000);

    std::vector<int16_t> kmer_map(KMER_COUNT * HV_DIM, 0);
    
    const char bases[] = {'A', 'C', 'T', 'G'};  // matching 2-bit encoding order
    
    for (int kmer_idx = 0; kmer_idx < KMER_COUNT; kmer_idx++) {
        // Decode index back to k-mer string
        std::string kmer(KMER_SIZE, 'A');
        for (int pos = 0; pos < KMER_SIZE; pos++)
            kmer[pos] = bases[(kmer_idx >> (pos * 2)) & 0x3];
        
        // Look up in cache — if not found (e.g. canonical form is different), leave as zeros
        auto it = cache.kmers.find(kmer);
        if (it == cache.kmers.end()) continue;
        
        // Unpack bit-packed HV into int16 0/1
        const HV& hv = it->second;
        for (int d = 0; d < HV_DIM; d++)
            kmer_map[kmer_idx * HV_DIM + d] = (hv[d / 64] >> (d % 64)) & 1;
    }

    std::vector<std::string> queries = {
        "",
        "",
        "",
        ""
    };
    auto HVs = encode(kmer_map, queries);
    std::cout << "Encoded!";
}